<script setup lang="ts">
import {ref,nextTick} from 'vue';import {RouterLink} from 'vue-router';
export interface Message{id:number;userId:number;username:string;content:string;createdAt:string;parentId:number|null;rootId:number|null;mediaUrl:string|null;replyToUsername:string|null;replyCount:number}
defineProps<{message:Message;canDelete?:boolean}>();defineEmits<{reply:[message:Message];remove:[id:number]}>();const viewer=ref<HTMLDialogElement|null>(null),viewing=ref(false);async function showImage(){viewing.value=true;await nextTick();viewer.value?.showModal();}
</script>
<template><div class="bubble-row" :id="'message-'+message.id" :data-message-id="message.id" tabindex="-1"><RouterLink :to="'/people/'+message.userId"><img class="avatar" :src="'/api/conversations/avatars/'+message.userId" alt="发言者头像，查看主页"></RouterLink><div class="bubble-body"><header><strong>{{message.username}}</strong><time>{{message.createdAt}}</time></header><small v-if="message.replyToUsername">回复 @{{message.replyToUsername}} · #{{message.parentId}}</small><p>{{message.content}}</p><button v-if="message.mediaUrl" class="media-button" aria-label="查看发言原图" @click="showImage"><img class="message-media" :src="message.mediaUrl" alt="发言图片或表情包" loading="lazy"></button><button v-if="message.content!=='（作者已删除）'" class="reply-button" @click="$emit('reply',message)">回复</button><button v-if="canDelete&&message.content!=='（作者已删除）'" class="reply-button" @click="$emit('remove',message.id)"> · 删除我的发言</button></div><dialog ref="viewer" class="image-viewer" @close="viewing=false" @click="viewer?.close()"><button aria-label="关闭原图">×</button><img v-if="viewing&&message.mediaUrl" :src="message.mediaUrl" alt="发言原图"></dialog></div></template>
<style scoped>.bubble-row{display:flex;gap:12px;margin:20px 0;align-items:flex-start}.avatar{width:40px;height:40px;object-fit:cover;border-radius:50%;flex-shrink:0}.bubble-body{flex:1;min-width:0;background:#f5f3ed;padding:15px 18px;border-radius:0 13px 13px}.bubble-body header{display:flex;gap:15px;flex-wrap:wrap;align-items:center}strong{font-size:13px;color:#304b49}time,small{font-size:10px;color:#8c8e7e}small{display:block;margin-top:8px}p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8;margin:10px 0}.media-button{display:block;background:none;border:0;padding:0;cursor:zoom-in}.message-media{max-width:min(240px,100%);max-height:180px;object-fit:contain;border-radius:8px}.reply-button{background:none;border:0;color:#94744c;font-size:11px;padding:8px 0 0;cursor:pointer}.image-viewer{padding:10px;border:0;border-radius:12px;max-width:95vw;max-height:95vh;background:#fff}.image-viewer::backdrop{background:#000b}.image-viewer img{max-width:88vw;max-height:85vh;object-fit:contain}.image-viewer button{position:absolute;right:10px;top:10px;background:#fff;border:0;border-radius:50%;font-size:24px;cursor:pointer}@media(max-width:500px){.avatar{width:32px;height:32px}.bubble-body{padding:12px}.bubble-row{gap:8px}}</style>
